(9888, '치유의 손길', 'Toucher guérisseur', 'Heilende Berührung', '治疗之触', '治療之觸', 'Toque curativo', '9 레벨', 'Rang 9', 'Rang 9', '等级 9', '等級 9', 'Rango 9', '대상의 생명력을 $s1만큼 회복시킵니다.', 'Rend $s1 points de vie à une cible alliée.', 'Heilt ein befreundetes Ziel um $s1 Punkt(e).', '治疗友方目标，恢复$s1点生命值。', '治療友方目標，恢復$s1點生命力。', 'Cura un objetivo amigo en $s1 p.', '', '', '', '', '', ''),
(9889, '치유의 손길', 'Toucher guérisseur', 'Heilende Berührung', '治疗之触', '治療之觸', 'Toque curativo', '10 레벨', 'Rang 10', 'Rang 10', '等级 10', '等級 10', 'Rango 10', '대상의 생명력을 $s1만큼 회복시킵니다.', 'Rend $s1 points de vie à une cible alliée.', 'Heilt ein befreundetes Ziel um $s1 Punkt(e).', '治疗友方目标，恢复$s1点生命值。', '治療友方目標，恢復$s1點生命力。', 'Cura un objetivo amigo en $s1 p.', '', '', '', '', '', ''),
